function formStart(string $action,string $back):string{global $csrf;return '<form method="post"><input type="hidden" name="csrf" value="'.App::h($csrf).'"><input type="hidden" name="action" value="'.App::h($action).'"><input type="hidden" name="back" value="'.App::h($back).'">';}
function checked(mixed $v):string{return $v?'checked':'';}
function mediaStatusClass(string $status):string{return $status==='completed'?'good':(in_array($status,['failed','completed_with_errors','cancelled'],true)?'bad':'wait');}
function mediaMetric(int|float|string|null $bytes):string{$bytes=(float)($bytes??0);if($bytes<=0)return '—';$units=['B/s','KB/s','MB/s','GB/s'];$i=0;while($bytes>=1024&&$i<count($units)-1){$bytes/=1024;$i++;}return number_format($bytes,$i>0?1:0).' '.$units[$i];}
function mediaBytes(int|float|string|null $bytes):string{$bytes=(float)($bytes??0);if($bytes<=0)return '—';$units=['B','KB','MB','GB','TB'];$i=0;while($bytes>=1024&&$i<count($units)-1){$bytes/=1024;$i++;}return number_format($bytes,$i>0?1:0).' '.$units[$i];}
function mediaEta(mixed $seconds):string{if($seconds===null||$seconds===''||(int)$seconds<0)return '—';$seconds=(int)$seconds;if($seconds<60)return $seconds.' ثانیه';if($seconds<3600)return intdiv($seconds,60).' دقیقه';return intdiv($seconds,3600).' ساعت '.intdiv($seconds%3600,60).' دقیقه';}
