ackground:linear-gradient(90deg,#2167d3,#20a67a);border-radius:20px}.badge{display:inline-block;padding:4px 8px;border-radius:20px;background:#edf2f8;color:#40516a;font-size:11px;white-space:nowrap}.badge.good{background:#dff7e9;color:#126a45}.badge.bad{background:#ffe4e4;color:#a62634}.badge.wait{background:#fff0cf;color:#8b5b00}.notice{padding:12px 14px;border:1px solid #f0d28a;background:#fff8e2;border-radius:10px;line-height:1.9;margin-bottom:16px}.table-wrap{overflow:auto}.engine{border-right:4px solid #2167d3}.event{padding:10px 12px;border-right:4px solid #94a3b8;background:#f8fafc;margin:8px 0;border-radius:7px}.event.error{border-color:#d73b4b;background:#fff4f4}.event.success{border-color:#15895c;background:#effaf5}.event.warning{border-color:#d88312;background:#fff9ec}@media(max-width:850px){.layout{display:block}nav{display:flex;overflow:auto;gap:4px;border:0}nav a{white-space:nowrap}main{padding:12px}.top{padding:12px}.search{display:block}.search button{margin-top:8px}}
