',''))?>" placeholder="/usr/bin/aria2c"></label><label>مسیر ffmpeg<input class="ltr" name="downloader_ffmpeg_path" value="<?=App::h(App::setting('downloader_ffmpeg_path',''))?>" placeholder="/usr/bin/ffmpeg"></label><label>مسیر MediaInfo<input class="ltr" name="downloader_mediainfo_path" value="<?=App::h(App::setting('downloader_mediainfo_path',''))?>" placeholder="/usr/bin/mediainfo"></label></div><button>ذخیره تنظیمات</button></form></div></div>
