<div class="card"><h3>دسته‌های دانلود</h3><div class="table-wrap"><table><tr><th>#</th><th>عنوان / محصول</th><th>وضعیت</th><th>پیشرفت</th><th>موفق / خطا</th><th>ساخته‌شده</th><th>کنترل</th></tr><?php foreach($mediaBatches as $batch):$batchProgress=(int)$batch['total_items']>0?(int)round(((int)$batch['completed_items']+(int)$batch['failed_items'])/(int)$batch['total_items']*100):0;?><tr><td>#<?=$batch['id']?></td><td><b><?=App::h($batch['title'])?></b><br><span class="muted"><?=App::h($batch['product_title']?:'محصول حذف‌شده')?> — <code><?=App::h($batch['channel_id'])?></code></span></td><td><span class="badge <?=mediaStatusClass($batch['status'])?>"><?=App::h(MediaQueue::statusLabel($batch['status']))?></span></td><td><?=$batchProgress?>٪<div class="progress"><span style="width:<?=$batchProgress?>%"></span></div></td><td><?=$batch['completed_items']?> / <?=$batch['failed_items']?> از <?=$batch['total_items']?></td><td><?=App::formatDate($batch['created_at'])?></td><td><div class="actions"><?php if(in_array($batch['status'],['queued','running'],true)):?><?=formStart('media_batch_control','downloader')?><input type="hidden" name="batch_id" value="<?=$batch['id']?>"><button class="gray small" name="operation" value="pause">توقف</button><button class="danger small" name="operation" value="cancel" onclick="return confirm('کل این دسته لغو شود؟')">لغو</button></form><?php elseif($batch['status']==='paused'):?><?=formStart('media_batch_control','downloader')?><input type="hidden" name="batch_id" value="<?=$batch['id']?>"><button class="ok small" name="operation" value="resume">ادامه</button><button class="danger small" name="operation" value="cancel">لغو</button></form><?php endif;if((int)$batch['failed_items']>0||$batch['status']==='completed_with_errors'):?><?=formStart('media_batch_control','downloader')?><input type="hidden" name="batch_id" value="<?=$batch['id']?>"><button class="warn small" name="operation" value="retry">تلاش مجدد خطاها</button></form><?php endif;?></div></td></tr><?php endforeach;?></table></div></div>
<div class="card"><h3>Jobهای Media</h3><div class="table-wrap"><table><tr><th># / منبع</th><th>عنوان</th><th>وضعیت / Worker</th><th>پیشرفت</th><th>سرعت دانلود</th><th>سرعت آپلود</th><th>ETA</th><th>Retry</th><th>عملیات</th></tr><?php foreach($mediaJobs as $job):?><tr><td>#<?=$job['id']?> / <?=$job['position']?><br><b><?=App::h($job['source_host'])?></b><br><span class="muted"><?=App::h(mb_strimwidth($job['source_url'],0,52,'…','UTF-8'))?></span></td><td><?=App::h($job['detected_title']?:$job['batch_title'])?><br><span class="muted"><?=App::h($job['product_title']?:'')?></span></td><td><span class="badge <?=mediaStatusClass($job['status'])?>"><?=App::h(MediaQueue::statusLabel($job['status']))?></span><br><code><?=App::h((string)($job['locked_by']??''))?></code></td><td><?=number_format((float)$job['progress'],0)?>٪<div class="progress"><span style="width:<?=max(0,min(100,(float)$job['progress']))?>%"></span></div></td><td><?=mediaMetric($job['download_speed_bps'])?></td><td><?=mediaMetric($job['upload_speed_bps'])?></td><td><?=mediaEta($job['eta_seconds'])?><?php if($job['next_attempt_at']):?><br><span class="muted">Retry: <?=App::formatDate($job['next_attempt_at'])?></span><?php endif;?></td><td>دانلود <?=$job['download_attempts']?> / <?=$job['max_attempts']?><br>آپلود <?=$job['upload_attempts']?> / <?=$job['max_attempts']?></td><td><?php if($job['error_message']):?><span class="muted"><?=App::h(mb_strimwidth($job['error_message'],0,100,'…','UTF-8'))?></span><br><?php endif;?><div class="actions"><a class="btn small" href="?tab=downloader&job=<?=$job['id']?>">رویدادها</a><?php if(in_array($job['status'],['failed','cancelled'],true)):?><?=formStart('media_job_control','downloader')?><input type="hidden" name="job_id" value="<?=$job['id']?>"><button class="warn small" name="operation" value="retry">Retry</button></form><?php endif;if(!in_array($job['status'],['completed','failed','cancelled'],true)):?><?=formStart('media_job_control','downloader')?><input type="hidden" name="job_id" value="<?=$job['id']?>"><button class="danger small" name="operation" value="cancel">Cancel</button></form><?php endif;if(in_array($job['status'],['completed','failed','cancelled'],true)):?><?=formStart('media_job_control','downloader')?><input type="hidden" name="job_id" value="<?=$job['id']?>"><button class="danger small" name="operation" value="delete" onclick="return confirm('این Job و رویدادهایش حذف شود؟')">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></table></div></div>
<?php elseif($tab==='channel_stats'):$channelRows=MediaQueue::channelRows();$scannerStatus=MediaQueue::historyScannerStatus();?><h2>آمار حرفه‌ای کانال‌های محصولات</h2><div class="notice">Bot API فقط پست‌های جدید را تحویل می‌دهد. برای شمارش فیلم‌ها و عکس‌های قبل از نصب ربات، اسکنر امن MTProto را یک‌بار با حسابی که عضو کانال است راه‌اندازی کن؛ سپس «اسکن کل تاریخچه» را بزن. محتوای فایل‌ها دانلود نمی‌شود و فقط نوع، حجم و شناسه پیام خوانده می‌شود.</div><div class="card"><div class="actions"><?=formStart('channel_stats_refresh','channel_stats')?><button class="ok">بروزرسانی همه کانال‌ها</button></form><a class="btn gray" href="?tab=products">مدیریت محصولات و کانال‌ها</a><span class="badge <?=$scannerStatus['ready']?'good':'wait'?>"><?=$scannerStatus['ready']?'اسکنر تاریخچه آماده است':'اسکنر تاریخچه تنظیم نشده'?></span></div><?php if(!$scannerStatus['ready']):?><p class="muted">روی سرور اجرا کن: <code>sudo /var/www/freebot/setup-channel-scanner.sh</code></p><?php endif;?></div><div class="card"><div class="table-wrap"><table><tr><th>محصول / کانال</th><th>اعضا / ادمین</th><th>دسترسی ربات</th><th>فروش</th><th>لینک اختصاصی</th><th>رسانه کل</th><th>اسکن تاریخی</th><th>دانلودر</th><th>آخرین بررسی</th><th>عملیات</th></tr><?php foreach($channelRows as $channel):?><tr><td><b><?=App::h($channel['product_title'])?></b><br><?=App::h($channel['channel_title']?:'عنوان دریافت نشده')?><?php if($channel['channel_username']):?> <span class="muted">@<?=App::h($channel['channel_username'])?></span><?php endif;?><br><code><?=App::h($channel['channel_id'])?></code></td><td><b><?=number_format((int)$channel['member_count'])?></b> عضو<br><span class="muted"><?=number_format((int)$channel['admin_count'])?> ادمین</span></td><td><span class="badge <?=$channel['can_post']?'good':'bad'?>"><?=$channel['can_post']?'آماده آپلود':'بدون دسترسی ارسال'?></span><br><span class="muted"><?=App::h($channel['bot_status']?:'بررسی نشده')?></span></td><td><b><?=number_format((int)$channel['sales_count'])?> خرید</b><br><span class="muted"><?=App::money($channel['sales_amount'])?></span></td><td><b><?=number_format((int)$channel['invite_count'])?></b> لینک ساخته‌شده</td><td><b>ویدیو: <?=number_format((int)$channel['video_count'])?></b><br>عکس: <?=number_format((int)$channel['photo_count'])?><br>فایل: <?=number_format((int)$channel['file_count'])?><br><span class="muted">کل پست: <?=number_format((int)$channel['tracked_posts'])?></span></td><td><span class="badge <?=($channel['history_scan_status']??'never')==='completed'?'good':(($channel['history_scan_status']??'never')==='failed'?'bad':'wait')?>"><?=App::h(['completed'=>'کامل','running'=>'در حال اجرا','failed'=>'خطا','never'=>'انجام نشده'][$channel['history_scan_status']??'never']??'انجام نشده')?></span><br><span class="muted"><?=App::formatDate($channel['history_scanned_at'])?> — <?=mediaBytes($channel['history_total_bytes'])?></span><?php if($channel['history_scan_error']):?><br><span class="badge bad"><?=App::h(mb_strimwidth($channel['history_scan_error'],0,90,'…','UTF-8'))?></span><?php endif;?></td><td><?=number_format((int)$channel['downloader_done'])?> آپلود موفق</td><td><?=App::formatDate($channel['refreshed_at'])?><?php if($channel['last_error']):?><br><span class="badge bad"><?=App::h(mb_strimwidth($channel['last_error'],0,90,'…','UTF-8'))?></span><?php endif;?></td><td><div class="actions"><?=formStart('channel_stats_refresh','channel_stats')?><input type="hidden" name="product_id" value="<?=$channel['id']?>"><button class="small">بروزرسانی</button></form><?=formStart('channel_history_scan','channel_stats')?><input type="hidden" name="product_id" value="<?=$channel['id']?>"><button class="warn small" <?=$scannerStatus['ready']?'':'disabled'?> onclick="return confirm('تمام تاریخچه قابل‌دسترسی این کانال اسکن شود؟')">اسکن کل تاریخچه</button></form></div></td></tr><?php endforeach;?></table></div></div>
