ass="ltr" id="shortcut-url" readonly value="<?=App::h($shortcut)?>" onclick="this.select()"><button type="button" onclick="navigator.clipboard.writeText(document.getElementById('shortcut-url').value)">کپی لینک</button></div><p class="muted">در Shortcuts یک Automation برای پیام بانک بساز، سپس Get Contents of URL را روی POST و JSON قرار بده و فیلد <code>message</code> را برابر متن همان پیامک بفرست. همین endpoint برای ارسال امن از ابزار اندرویدی نیز قابل استفاده است.</p><div class="actions"><?=formStart('payment_regen_shortcut','payments')?><button class="danger" onclick="return confirm('لینک فعلی باطل شود؟')">ساخت لینک محرمانه جدید</button></form><?=formStart('payment_process','payments')?><button>اجرای تطبیق همین حالا</button></form></div><p class="muted">آخرین اجرا: <?=App::h(App::setting('smart_sms_last_run_at','هنوز اجرا نشده'))?> | بررسی‌شده: <?=number_format((int)($lastResult['processed']??0))?> | تایید خودکار: <?=number_format((int)($lastResult['matched']??0))?></p></div><div class="card"><h3>آخرین پیامک‌های بانکی</h3><div class="table-wrap"><table><tr><th>#</th><th>منبع</th><th>مبلغ</th><th>وضعیت</th><th>فاکتور</th><th>زمان تراکنش</th><th>دریافت</th><th>متن خلاصه</th></tr><?php foreach(App::all('SELECT * FROM bank_sms ORDER BY id DESC LIMIT 100') as $r):?><tr><td>#<?=$r['id']?></td><td><?=App::h($r['source'])?></td><td><?=$r['amount_toman']!==null?App::money($r['amount_toman']):'نامشخص'?></td><td><span class="badge <?=in_array($r['status'],['matched'],true)?'good':(in_array($r['status'],['invalid','ignored'],true)?'bad':'wait')?>"><?=App::h($r['status'])?></span></td><td><?=$r['matched_topup_id']?'#'.(int)$r['matched_topup_id']:'—'?></td><td><?=$r['event_at']?App::formatDate($r['event_at']):'—'?></td><td><?=App::formatDate($r['received_at'])?></td><td><?=App::h(mb_strimwidth($r['raw_message'],0,100,'…','UTF-8'))?></td></tr><?php endforeach;?></table></div></div>
